from django.contrib.auth import password_validation
from rest_framework import serializers

from .models import SchoolMembership, UserSession


class DeviceSerializer(serializers.Serializer):
    """Device description sent by the client at login."""

    # Stable per-install identifier generated by the app (hashed server-side).
    identifier = serializers.CharField(max_length=255)
    device_name = serializers.CharField(max_length=120)
    device_type = serializers.ChoiceField(choices=["PHONE", "TABLET", "DESKTOP", "BROWSER"])
    platform = serializers.ChoiceField(choices=["ANDROID", "IOS", "WINDOWS", "MACOS", "LINUX", "WEB"])
    os_version = serializers.CharField(max_length=80, required=False, allow_blank=True)
    android_sdk = serializers.IntegerField(required=False, min_value=1)
    app_version = serializers.CharField(max_length=40, required=False, allow_blank=True)


class LoginSerializer(serializers.Serializer):
    identifier = serializers.CharField(max_length=254, help_text="Username or email.")
    # trim_whitespace=False: spaces can be part of a password.
    password = serializers.CharField(max_length=256, trim_whitespace=False, write_only=True)
    device = DeviceSerializer()


class RefreshSerializer(serializers.Serializer):
    refresh_token = serializers.CharField(max_length=512, write_only=True)


class PasswordChangeSerializer(serializers.Serializer):
    current_password = serializers.CharField(trim_whitespace=False, write_only=True)
    new_password = serializers.CharField(trim_whitespace=False, write_only=True)

    def validate_current_password(self, value):
        if not self.context["request"].user.check_password(value):
            raise serializers.ValidationError("Current password is incorrect.")
        return value

    def validate_new_password(self, value):
        # Same strength rules as everywhere else (settings.AUTH_PASSWORD_VALIDATORS).
        password_validation.validate_password(value, self.context["request"].user)
        return value


class MembershipSerializer(serializers.ModelSerializer):
    school_code = serializers.CharField(source="school.code")
    school_name = serializers.CharField(source="school.name")
    roles = serializers.SerializerMethodField()

    class Meta:
        model = SchoolMembership
        fields = ["id", "school_code", "school_name", "status", "is_primary_school", "roles"]

    def get_roles(self, obj):
        return sorted(obj.role_codes())


class SessionSerializer(serializers.ModelSerializer):
    device_name = serializers.CharField(source="device.device_name")
    platform = serializers.CharField(source="device.platform")
    is_current = serializers.SerializerMethodField()

    class Meta:
        model = UserSession
        fields = [
            "id",
            "device_name",
            "platform",
            "ip_address",
            "created_at",
            "last_used_at",
            "expires_at",
            "is_current",
        ]

    def get_is_current(self, obj):
        return obj.pk == getattr(self.context["request"].auth, "pk", None)


def token_payload(issued):
    """Response body shared by login and refresh."""
    from django.conf import settings

    return {
        "access_token": issued.access_token,
        "access_expires_in": int(settings.ACCESS_TOKEN_LIFETIME.total_seconds()),
        "refresh_token": issued.refresh_token,
        "refresh_expires_at": issued.session.expires_at,
        "session_id": str(issued.session.id),
    }
